// FITILA translation memory for the browser: works offline and online.
//
//   1. exact attested sentence (dictionary, Apprendre, scenes)   -> 100 % correct, instant
//   2. online: byt5-bariba-translate (its server also checks the memory first)
//   3. offline or server down: word-by-word from the lexicon, only if most words are known
//
// The data file /data/translation-memory.json is generated by
// scripts/dunya_translate/export_memory.py and precached by the PWA service worker.
// This module has no imports so it can be unit-tested outside the app bundle.

export type Direction = 'fr-ba' | 'ba-fr';

export interface MemoryData {
  v: number;
  pairs: Array<[string, string, string]>;
  fr2ba: Record<string, string>;
  ba2fr: Record<string, string>;
}

export interface MemoryResult {
  translation: string;
  confidence: number;
  method: 'translation-memory' | 'dictionary-offline';
  /** Provenance category: does not mean measured translation accuracy. */
  qualityStatus?: 'attested' | 'partial-lexical';
  /** Share of source words found (word-by-word only). */
  coverage?: number;
}

const TONE_MARKS = /[̀́̂̄̌]/g; // the nasal tilde U+0303 is kept

/** Same rules as scripts/dunya_translate/dunya_text.py `fold_ba`. */
export function foldBa(text: string): string {
  return (text || '')
    .normalize('NFC')
    .replace(/ɑ/g, 'a')
    .normalize('NFD')
    .replace(TONE_MARKS, '')
    .normalize('NFC')
    .toLowerCase()
    .replace(/’/g, "'")
    .replace(/[^\p{L}\p{N}̃' ]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Same rules as `fold_fr`. */
export function foldFr(text: string): string {
  return (text || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/’/g, "'")
    .replace(/[^a-z0-9' ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

export class TranslationMemory {
  private frToBa = new Map<string, [string, string]>();
  private baToFr = new Map<string, [string, string]>();

  constructor(private readonly data: MemoryData) {
    for (const [fr, ba, grade] of data.pairs) {
      const kf = foldFr(fr);
      const kb = foldBa(ba);
      if (!this.frToBa.has(kf)) this.frToBa.set(kf, [ba, grade]);
      if (!this.baToFr.has(kb)) this.baToFr.set(kb, [fr, grade]);
    }
  }

  get size(): number {
    return this.baToFr.size;
  }

  /** Attested translation of a whole sentence, or null. */
  exact(text: string, direction: Direction): MemoryResult | null {
    const hit = direction === 'fr-ba' ? this.frToBa.get(foldFr(text)) : this.baToFr.get(foldBa(text));
    if (!hit) return null;
    return { translation: hit[0], confidence: 0, method: 'translation-memory', qualityStatus: 'attested' };
  }

  /**
   * Word-by-word fallback for offline use. Longest match first (3, 2, 1 words).
   * Returns null when fewer than 60 % of the words are known: a half-translated
   * sentence is worse than an honest "not available offline".
   */
  wordByWord(text: string, direction: Direction): MemoryResult | null {
    const fold = direction === 'fr-ba' ? foldFr : foldBa;
    const map = direction === 'fr-ba' ? this.data.fr2ba : this.data.ba2fr;
    const words = fold(text).split(' ').filter(Boolean);
    if (words.length === 0) return null;
    const out: string[] = [];
    let known = 0;
    for (let i = 0; i < words.length; ) {
      let matched = false;
      for (let n = Math.min(3, words.length - i); n >= 1; n--) {
        const found = map[words.slice(i, i + n).join(' ')];
        if (found) {
          out.push(found);
          known += n;
          i += n;
          matched = true;
          break;
        }
      }
      if (!matched) {
        out.push(words[i]);
        i += 1;
      }
    }
    const coverage = known / words.length;
    // Never present a partially translated sentence as reliable. Unknown words
    // are not copied into the output as though translated.
    if (coverage < 1) return null;
    return {
      translation: out.join(' '),
      confidence: 0,
      qualityStatus: 'partial-lexical',
      method: 'dictionary-offline',
      coverage,
    };
  }

  /** Exact sentence first, then (if allowed) word by word. */
  lookup(text: string, direction: Direction, allowWordByWord = false): MemoryResult | null {
    return this.exact(text, direction) ?? (allowWordByWord ? this.wordByWord(text, direction) : null);
  }
}

let loading: Promise<TranslationMemory | null> | null = null;

/** Loads the memory once; resolves to null (never throws) if the file is unavailable. */
export function loadTranslationMemory(): Promise<TranslationMemory | null> {
  if (!loading) {
    loading = (async () => {
      try {
        const response = await fetch('/data/translation-memory.json', { cache: 'force-cache' });
        if (!response.ok) return null;
        return new TranslationMemory((await response.json()) as MemoryData);
      } catch {
        return null;
      }
    })();
    // A failed load (e.g. first visit while offline) must be retried later.
    loading.then((memory) => {
      if (!memory) loading = null;
    });
  }
  return loading;
}

/** Network is down or unreachable (as opposed to a server-side translation error). */
export function isOffline(): boolean {
  return typeof navigator !== 'undefined' && navigator.onLine === false;
}

export async function memoryTranslate(
  text: string,
  direction: Direction,
  opts: { allowWordByWord?: boolean } = {},
): Promise<MemoryResult | null> {
  const memory = await loadTranslationMemory();
  return memory ? memory.lookup(text, direction, opts.allowWordByWord) : null;
}
